/* From Uiverse.io by rmdhnkhsn  - Tags: simple, green, card, css effect, card template, cardhover , card animation, card hover */
.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  max-width: 500px;
  padding: 42px 32px;
  flex-direction: column;
  align-items: flex-start;
  border-radius: 30px;
  border: 2px solid #f8f9fd;
  background: #fff;
  transition: 1s all;
  text-decoration: none;
}
.__UIV_SCOPE__ .title {
  color: #072713;
  text-align: center;
  font-size: 22px;
  font-style: normal;
  font-weight: 600;
  line-height: 35.196px;
  transition: 0.4s all;
}
.__UIV_SCOPE__ .subtitle {
  color: #7e8882;
  text-align: center;
  font-size: 14px;
  font-style: normal;
  font-weight: 400;
  line-height: 22px;
  transition: 0.4s all;
}
.__UIV_SCOPE__ .icon-circle {
  position: absolute;
  top: 0;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  justify-content: center;
  align-items: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #e5f6eb;
}
.__UIV_SCOPE__ .card:hover {
  background: #23c55e;
  transition: 0.4s all;
}
.__UIV_SCOPE__ .card:hover .title,
.__UIV_SCOPE__ .card:hover .subtitle {
  color: #fff;
  transition: 0.4s all;
}
.__UIV_SCOPE__ .btnRound {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  height: 30px;
  padding: 6px 28px;
  border-radius: 100px;
  border: 1px solid #23c55e;
  background: #fff;
  transition: all 0.2s ease;
}
.__UIV_SCOPE__ .btnRound:hover {
  box-shadow: 0px 6px 10px 0px rgba(35, 197, 94, 0.2);
  transition: all 0.2s ease;
}
.__UIV_SCOPE__ .btnService {
  position: absolute;
  bottom: -30px;
  left: 50%;
  transform: translate(-50%, -50%);
}
